class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']

    def _ck_bind_link(self, setup, dut, misc, role):
        """Resolve `[misc] ck_link_<role>` on THIS bench, bind it, and assert its media.

        Fixed frame — do not edit or delete. Three failures it converts from silent to loud:
          1. an undeclared role: the bench has not agreed to host this test;
          2. `init_portlink()` returning (None, None) for a link the bench does not have —
             a None port later renders as `interface None`, so the run fails looking like a
             SCRIPT defect;
          3. the bound port being the wrong MEDIA. That one cannot be caught offline: media
             belongs to the pluggable, and the CLI accepts `polarity`/`speed 100` on fibre
             where they are meaningless, so the run would report a PRODUCT failure that is
             really a cabling error.
        Raising aborts the suite on purpose: "this bench cannot host this test" is not a
        test result. See ask-ck/pytest-create/TOPOLOGY-PROFILES.md.
        """
        import ck_media
        ref = misc.get('ck_link_' + role)
        if not ref:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: this .setup declares no "
                "ck_link_%s, so the %s link this test needs is not available here. "
                "See TOPOLOGY-PROFILES.md." % (role, role))
        dev_a, dev_b, _named_port = ck_media.parse_link_ref(ref)
        dut_key = misc.get('ck_role_dut', 'swi_a')
        far_key = dev_b if dev_a == dut_key else dev_a
        if far_key == 'tb':
            # The TESTBOX end of a data link (`ck_link_tb = tb-<dut>:<eth>`): the far
            # object is the testbox itself and its port is an Eth, so the ART shape
            # `(dut.portA, tb.ethA) = setup.init_portlink(dut, tb, type1='port')` applies.
            far = self.tb
            (near_port, far_port) = setup.init_portlink(dut, far, type1='port')
        else:
            far = setup.init_swi(far_key)
            (near_port, far_port) = setup.init_portlink(dut, far, type1='port', type2='port')
        if near_port is None or far_port is None:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: ck_link_%s = %r but no unused "
                "matching [portlink] exists between %s and %s." % (role, ref, dut_key, far_key))
        status = dut.cmd('show interface %s status' % near_port.name)
        ok, why = ck_media.assert_role_media(status, near_port.name, role)
        if not ok:
            raise RuntimeError(why)
        self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
            role, dut_key, near_port.name, far_key, far_port.name, why))
        return near_port, far_port, far

    def init(self, setup):
        # Topology is resolved from the .setup [misc] ROLE CONTRACT at run time, so this
        # script names no device and no port: it binds correctly on any bench that declares
        # the roles it needs, and fails loudly on one that does not. The role names come
        # from TOPOLOGY-PROFILES.md; the bench says what they mean HERE.
        tb = setup.init_tb()
        misc = setup.get_all_misc()
        dutA = setup.init_swi(misc.get('ck_role_dut', 'swi_a'))
        
        stk_a = setup.init_stk('stk_a')
        self.tb = tb
        self.dutA = dutA
        self.stk_a = stk_a
        # The TESTBOX data link (profile `tblink`): the ART shape `(dut.portA, tb.ethA)`.
        # Captures, injected frames and pings happen on `tb.ethA`; `dutA.portA` is the
        # DUT port under test at the other end of that cable.
        (dutA.portA, tb.ethA, _tb) = self._ck_bind_link(setup, dutA, misc, 'tb')
        # The NEIGHBOUR switch (profile `copper`), taken from the far end of the one
        # link the case needs — no second lookup, and deterministic on purpose: this used to
        # be a FILL slot and the model declared links the test never used (T33235 bound 4
        # devices and 2 links while referencing 1 of each). Named `peer`, never `dut`: in
        # ART `dut` is the DUT's own stack handle, and a partner called `dut` made every
        # model read `dut.portA` as the DUT's port (T44297, 2026-09-07).
        (dutA.portPeer, peer_port, peer) = self._ck_bind_link(
            setup, dutA, misc, 'copper')
        peer.portDut = peer_port
        self.peer = peer
        # NOT BOUND: dutC, ethLink.
        # A test binds the DUT plus ONE partner (the far end of its one link). These names
        # were only ever inferred from the vocabulary of the selected fragments, which is not
        # evidence the test needs them — and every unused binding becomes a topology demand
        # a bench has to satisfy for nothing. Needing a second partner means declaring a
        # second link role in TOPOLOGY-PROFILES.md, not guessing a device here.

    def configure(self):
        tb = self.tb
        dutA = self.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.stk_a
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # setup: Enable LLDP globally on the device under test (`lldp run` at global config) and on the test port set it to transmit and receive (`lldp transmit`, `lldp receive`). Bring up the physical link from the test port to the partner switch, configure the partner port to receive LLDP so it records neighbour information, and start a packet capture (tcpdump/Scapy) on the link so transmitted LLDPDUs can be decoded.
        dutA.mode(')#')
        dutA.cmd('lldp run')
        dutA.cmd('interface {},{}'.format(portA.name, portPeer.name))
        dutA.cmd('lldp transmit')
        dutA.cmd('lldp receive')
        dutA.mode('#')

        peer.mode(')#')
        peer.cmd('lldp run')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('lldp transmit')
        peer.cmd('lldp receive')
        peer.mode('#')

        wait_for_port_link_up(self, dutA, [portA, portPeer])
        wait_for_port_link_up(self, peer, [portDut])

    def tear_down(self):
        tb = self.tb
        dutA = self.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.stk_a
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        dutA.mode(')#')
        dutA.cmd('interface {},{}'.format(portA.name, portPeer.name))
        dutA.cmd('no lldp transmit')
        dutA.cmd('no lldp receive')
        dutA.cmd('no lldp run')
        dutA.mode('#')

        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no lldp transmit')
        peer.cmd('no lldp receive')
        peer.cmd('no lldp run')
        peer.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = 'On the test port select only the port-description optional TLV (`lldp tlv-select port-description`).'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'On the test port select only the port-description optional TLV (`lldp tlv-select port-description`).\n'
    testCaseMethod += 'Verify: `show lldp interface <port>` lists port-description as an enabled/selected TLV, and a captured LLDPDU from the test port decodes a Port Description TLV.\n'

    PORT_DESC_STR = 'lldpTlvT44297desc'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Per-case PRECONDITIONS: select only the port-description optional TLV on the
        # test port, and give the port a description so the transmitted Port Description
        # TLV carries a value we can positively identify in the capture.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('description {}'.format(self.PORT_DESC_STR))
        dutA.cmd('lldp tlv-select port-description')
        dutA.mode('#')

    def main(self):
        # ART 1331_past_issues/test-1331.1001.py lines 760-784
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 1: On the test port select only the port-description optional TLV (`lldp tlv-select port-description`).')

        dutA.mode('#')
        if not wait_for_port_link_up(self, dutA, [portA]):
            self.failed('port {} did not come up before the LLDP TLV check'.format(portA.name))
            return

        countersBefore = getPortCo(dutA, portA.name, interface=True)
        self.log('Port counters before capture:\n{}'.format(countersBefore))

        output = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(output))

        name = portA.name
        short = name[4:] if name.startswith('port') else name
        row = None
        for line in output.splitlines():
            tokens = line.strip().lstrip('*').split()
            if tokens[:1] == [name] or tokens[:1] == [short]:
                row = line.strip().lstrip('*')
                break

        if row is None:
            self.failed('port {} is missing from "show lldp interface" output'.format(name))
            return

        rowTokens = row.split()
        baseCol = rowTokens[6] if len(rowTokens) > 6 else ''
        if baseCol.startswith('Pd'):
            self.passed('show lldp interface {} lists port-description (Pd) enabled in the Base TLV column: {}'.format(name, baseCol))
        else:
            self.failed('show lldp interface {} Base TLV column is "{}", port-description (Pd) not enabled'.format(name, baseCol))
            return

        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether proto 0x88cc')
        self.log('Capturing LLDPDUs on {} across the LLDP tx interval'.format(ethA))
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        countersAfter = getPortCo(dutA, portA.name, interface=True)
        self.log('Port counters after capture:\n{}'.format(countersAfter))

        if len(recPktList) == 0:
            self.failed('No LLDP frames were captured on {}'.format(ethA))
            return
        self.passed('{} LLDP frame(s) captured on {}'.format(len(recPktList), ethA))

        analyse_lldp_packets(self, recPktList)

        descBytes = self.PORT_DESC_STR.encode('utf-8')
        found = False
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic) and descBytes in bytes(pkt):
                found = True
                log_packet(self, pkt)
                break

        if found:
            self.passed('Captured LLDPDU decodes a Port Description TLV containing the configured description "{}"'.format(self.PORT_DESC_STR))
        else:
            self.failed('No captured LLDPDU contained a Port Description TLV with the configured description "{}"'.format(self.PORT_DESC_STR))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Mirror of configure(): remove the port-description TLV selection and the
        # description string that was applied to identify the TLV in the capture.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select port-description')
        dutA.cmd('no description')
        dutA.mode('#')


class TestCase_2(ATTestCase.TestCase):
    testCaseDesc = 'On the test port additionally select the system-name optional TLV (`lldp tlv-select system-name`).'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'On the test port additionally select the system-name optional TLV (`lldp tlv-select system-name`).\n'
    testCaseMethod += 'Verify: `show lldp interface <port>` shows system-name selected, and a captured LLDPDU decodes a System Name TLV.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select system-name')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 283-295
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 2: On the test port additionally select the system-name optional TLV (`lldp tlv-select system-name`).')

        dutA.mode('#')
        output = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(output))

        portToken = portA.name.replace('port', '')
        row = None
        for line in output.splitlines():
            tokens = line.split()
            if tokens and tokens[0].lstrip('*') == portToken:
                row = line
                break

        if row is None:
            self.failed('port {} missing from show lldp interface output'.format(portA.name))
            return

        baseField = row.split()[-4]
        if 'Sn' in baseField:
            self.passed('show lldp interface {} Base TLV field "{}" includes Sn (System Name selected)'.format(portA.name, baseField))
        else:
            self.failed('show lldp interface {} Base TLV field "{}" does not include Sn (System Name not selected)'.format(portA.name, baseField))
            return

        self.log('---- Capture LLDPDU transmitted by {} on {}'.format(portA.name, ethA.name))
        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        if len(recPktList) == 0:
            self.failed('No LLDP frames captured on {}'.format(ethA.name))
            return
        self.passed('{} LLDP frames captured on {}'.format(len(recPktList), ethA.name))

        analyse_lldp_packets(self, recPktList)

        local_info = dutA.cmd('show lldp local-info interface {}'.format(portA.name))
        sysNameLine = next((l for l in local_info.splitlines() if 'System Name' in l), None)
        if sysNameLine is None:
            self.failed('System Name not found in show lldp local-info interface {}'.format(portA.name))
            return
        sysName = sysNameLine.split('.')[-1].strip()
        self.log('DUT configured System Name = {}'.format(sysName))

        sysNameBytes = sysName.encode('utf-8')
        foundSysNameTlv = False
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic) and sysNameBytes in bytes(pkt):
                foundSysNameTlv = True
                break

        if foundSysNameTlv:
            self.passed('Captured LLDPDU on {} contains System Name TLV value "{}"'.format(ethA.name, sysName))
        else:
            self.failed('No captured LLDPDU on {} contains System Name TLV value "{}"'.format(ethA.name, sysName))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select system-name')
        dutA.mode('#')


class TestCase_3(ATTestCase.TestCase):
    testCaseDesc = 'On the test port additionally select the system-description optional TLV (`lldp tlv-select system-description`).'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'On the test port additionally select the system-description optional TLV (`lldp tlv-select system-description`).\n'
    testCaseMethod += 'Verify: `show lldp interface <port>` shows system-description selected, and a captured LLDPDU decodes a System Description TLV.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition this step presumes: the test port has the system-description
        # optional TLV additionally selected for LLDP transmission.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select system-description')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 270-282
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 3: On the test port additionally select the system-description optional TLV (`lldp tlv-select system-description`).')

        dutA.mode('#')
        ifaceOutput = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(ifaceOutput))

        row = None
        for line in ifaceOutput.splitlines():
            parts = line.lstrip('*').split()
            if parts and 'port{}'.format(parts[0]) == portA.name:
                row = line
                break

        if row is None:
            self.failed('{} is missing from show lldp interface output'.format(portA.name))
            return

        if 'Sd' in row:
            self.passed('show lldp interface {} shows system-description (Sd) selected in Base TLVs: {}'.format(portA.name, row.strip()))
        else:
            self.failed('show lldp interface {} does not show system-description (Sd) selected in Base TLVs: {}'.format(portA.name, row.strip()))
            return

        localInfo = dutA.cmd('show lldp local-info interface {}'.format(portA.name))
        self.log(localInfo)
        sysDesc = ''
        for line in localInfo.splitlines():
            if 'System Description' in line and '.' in line:
                sysDesc = line.split('...')[-1].strip()
                break

        if not sysDesc:
            self.failed('Unable to retrieve the local System Description value from show lldp local-info interface {}'.format(portA.name))
            return

        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether proto 0x88cc and ether dst 01:80:c2:00:00:0e')
        self.log('Waiting for {} to transmit an LLDPDU carrying the System Description TLV'.format(portA.name))
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        if len(recPktList) == 0:
            self.failed('No LLDPDU frames were captured on {} from {}'.format(ethA, portA.name))
            return

        self.passed('{} LLDPDU frame(s) captured on {}'.format(len(recPktList), ethA))

        analyse_lldp_packets(self, recPktList)

        sysDescFound = False
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic) and sysDesc.encode() in bytes(pkt):
                sysDescFound = True
                break

        if sysDescFound:
            self.passed('Captured LLDPDU decodes a System Description TLV matching CLI value "{}"'.format(sysDesc))
        else:
            self.failed('No captured LLDPDU decoded a System Description TLV matching CLI value "{}"'.format(sysDesc))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select system-description')
