class TestCase_6(ATTestCase.TestCase):
    testCaseDesc = 'With the complete optional TLV set now selected on the test port, capture several consecutive LLDPDUs from the test port.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'With the complete optional TLV set now selected on the test port, capture several consecutive LLDPDUs from the test port.\n'
    testCaseMethod += 'Verify: Every captured LLDPDU carries the mandatory Chassis ID, Port ID and Time To Live TLVs plus all five selected optional TLVs (port description, system name, system description, system capabilities, management address) and ends with the End Of LLDPDU marker.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition this step presumes: the complete set of optional base LLDP TLVs
        # (port description, system name, system description, system capabilities,
        # management address) selected for transmission on the test port.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select port-description system-name system-description system-capabilities management-address')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 335-344
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 6: With the complete optional TLV set now selected on the test port, capture several consecutive LLDPDUs from the test port.')

        # First confirm, from the CLI, that the full optional Base TLV set is actually
        # selected for transmission on the test port (Base column with no dashes).
        dutA.mode('#')
        ifOutput = dutA.cmd('show lldp interface {}'.format(portA.name))
        suffix = portA.name[4:] if portA.name.startswith('port') else portA.name
        baseRow = None
        for line in ifOutput.splitlines():
            tokens = line.lstrip('*').split()
            if tokens[:1] == [suffix]:
                baseRow = line.lstrip('*').split()
                break
        if baseRow is None or len(baseRow) < 5 or baseRow[4] != 'PdSnSdScMa':
            self.failed('show lldp interface {} does not report the full Base TLV set (PdSnSdScMa) selected: {}'.format(
                portA.name, baseRow))
            return
        self.passed('show lldp interface {} confirms all five optional Base TLVs are selected for Tx (Base={})'.format(
            portA.name, baseRow[4]))

        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA.name),
                                    'ether dst 01:80:c2:00:00:0e')
        self.log('Waiting for several consecutive LLDPDU transmissions on {}'.format(ethA.name))
        time.sleep(95)
        recPktList = tb.stop_tcpdump(subProc)

        output = '{} LLDP frames captured on {}'.format(len(recPktList), ethA.name)
        self.log('OBSERVED: {}'.format(output))

        if len(recPktList) < 2:
            self.failed('Only {} LLDPDU(s) were captured on {}; expected several consecutive frames'.format(
                len(recPktList), ethA.name))
            return
        self.passed('{} consecutive LLDPDUs captured on {}'.format(len(recPktList), ethA.name))

        analyse_lldp_packets(self, recPktList)

        allMandatory = True
        allOptional = True
        allEnd = True
        for idx, pkt in enumerate(recPktList):
            pktNum = idx + 1
            if pkt.haslayer(lldp_basic) and pkt[lldp_basic].chassis_id and pkt[lldp_basic].port_id and pkt[lldp_basic].ttl_val is not None:
                self.log('Packet {}: mandatory Chassis ID/Port ID/TTL TLVs present (chassis={}, port={}, ttl={})'.format(
                    pktNum, pkt[lldp_basic].chassis_id, pkt[lldp_basic].port_id, pkt[lldp_basic].ttl_val))
            else:
                self.log('Packet {}: missing a mandatory Chassis ID/Port ID/TTL TLV'.format(pktNum))
                allMandatory = False

            if pkt.haslayer(lldp_base_cap_tlv) and pkt.haslayer(lldp_man_tlv):
                self.log('Packet {}: System Capabilities and Management Address TLVs present (mgmt addr={})'.format(
                    pktNum, pkt[lldp_man_tlv].lldp_man_val))
            else:
                self.log('Packet {}: missing System Capabilities or Management Address TLV'.format(pktNum))
                allOptional = False

            if pkt.haslayer(lldp_end_tlv):
                self.log('Packet {}: End Of LLDPDU marker present'.format(pktNum))
            else:
                self.log('Packet {}: missing End Of LLDPDU marker'.format(pktNum))
                allEnd = False

        if allMandatory:
            self.passed('Every captured LLDPDU carried the mandatory Chassis ID, Port ID and TTL TLVs')
        else:
            self.failed('One or more captured LLDPDUs were missing a mandatory Chassis ID/Port ID/TTL TLV')

        if allOptional:
            self.passed('Every captured LLDPDU carried the selected System Capabilities and Management Address optional TLVs, consistent with the port-description/system-name/system-description/system-capabilities/management-address set confirmed selected via the CLI')
        else:
            self.failed('One or more captured LLDPDUs were missing a selected optional Base TLV (System Capabilities/Management Address)')

        if allEnd:
            self.passed('Every captured LLDPDU ended with the End Of LLDPDU marker')
        else:
            self.failed('One or more captured LLDPDUs did not end with the End Of LLDPDU marker')

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Mirror configure(): deselect the optional Base TLV set on the test port.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select port-description system-name system-description system-capabilities management-address')
        dutA.mode('#')


class TestCase_7(ATTestCase.TestCase):
    testCaseDesc = 'With all optional TLVs selected, capture LLDPDUs and inspect the TLV list for the single-instance optional TLVs.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'With all optional TLVs selected, capture LLDPDUs and inspect the TLV list for the single-instance optional TLVs.\n'
    testCaseMethod += 'Verify: No captured LLDPDU contains more than one Port Description, System Name, System Description or System Capabilities TLV — each single-instance optional TLV appears at most once per LLDPDU.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition this step presumes: all optional base and MED TLVs selected
        # for transmission on the port facing the testbox capture point.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select all')
        dutA.cmd('lldp med-tlv-select all')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 61-83
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 7: With all optional TLVs selected, capture LLDPDUs and inspect the TLV list for the single-instance optional TLVs.')

        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA.name),
                                    'ether dst 01:80:c2:00:00:0e')
        self.log('Waiting for {} to transmit an LLDPDU on {} (default LLDP transmit interval)'.format(portA.name, ethA.name))
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        lldpPktList = [pkt for pkt in recPktList if pkt.haslayer(lldp_basic)]
        output = '{} frames captured on {}, {} decodable as LLDPDU'.format(len(recPktList), ethA.name, len(lldpPktList))
        self.log('OBSERVED: {}'.format(output))

        if len(lldpPktList) == 0:
            self.failed('No LLDPDU captured from {} on {}'.format(portA.name, ethA.name))
            return
        self.passed('{} LLDPDU(s) captured from {}'.format(len(lldpPktList), portA.name))

        analyse_lldp_packets(self, lldpPktList)

        tlvNames = {4: 'Port Description', 5: 'System Name', 6: 'System Description', 7: 'System Capabilities'}
        violation = None
        for idx, pkt in enumerate(lldpPktList):
            raw = bytes(pkt[lldp_basic])
            counts = {4: 0, 5: 0, 6: 0, 7: 0}
            i = 0
            while i + 2 <= len(raw):
                header = (raw[i] << 8) | raw[i + 1]
                tlv_type = header >> 9
                tlv_len = header & 0x01FF
                if tlv_type == 0 and tlv_len == 0:
                    break
                if tlv_type in counts:
                    counts[tlv_type] += 1
                i += 2 + tlv_len
            self.log('LLDPDU #{} TLV counts: {}'.format(idx + 1, counts))
            for tlv_type, count in counts.items():
                if count > 1:
                    violation = 'LLDPDU #{} contains {} instances of the {} TLV'.format(idx + 1, count, tlvNames[tlv_type])
                    break
            if violation:
                break

        if violation is None:
            self.passed('No captured LLDPDU contains more than one Port Description, System Name, System Description or System Capabilities TLV — each single-instance optional TLV appears at most once per LLDPDU.')
        else:
            self.failed(violation)

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp med-tlv-select all')
        dutA.cmd('no lldp tlv-select all')
        dutA.mode('#')


