class TestCase_15(ATTestCase.TestCase):
    testCaseDesc = 'Clear only the port-description TLV on the test port (`no lldp tlv-select port-description`), leaving the other optional TLVs selected, and capture LLDPDUs.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'Clear only the port-description TLV on the test port (`no lldp tlv-select port-description`), leaving the other optional TLVs selected, and capture LLDPDUs.\n'
    testCaseMethod += 'Verify: `show lldp interface <port>` shows port-description no longer selected while the other optional TLVs remain selected; captured LLDPDUs no longer carry a Port Description TLV but still carry the remaining selected TLVs.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition this step presumes: port-description AND management-address both
        # selected for transmission on the test port, so main() can clear ONLY
        # port-description and prove the other TLV (management-address) survives.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select port-description management-address')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 61-83
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 15: Clear only the port-description TLV on the test port (`no lldp tlv-select port-description`), leaving the other optional TLVs selected, and capture LLDPDUs.')

        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select port-description')
        dutA.mode('#')

        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether proto 0x88cc')
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        output = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(output))

        if len(recPktList) == 0:
            self.failed('No LLDPDU frames were captured on {} after clearing the port-description TLV'.format(ethA.name))
            return
        self.passed('{} LLDPDU frames captured on {}'.format(len(recPktList), ethA.name))

        analyse_lldp_packets(self, recPktList)

        row = next((l for l in output.splitlines() if l.split()[:1] == [portA.name]), None)
        if row is None:
            self.failed('port {} missing from show lldp interface output'.format(portA.name))
            return
        baseField = row.split()[-4]
        if baseField[0:2] != 'Pd' and baseField[-2:] == 'Ma':
            self.passed('show lldp interface {} Base TLVs field {} shows port-description cleared while management-address remains selected'.format(portA.name, baseField))
        else:
            self.failed('show lldp interface {} Base TLVs field {} still shows port-description selected or lost management-address'.format(portA.name, baseField))

        pdFound = False
        maFound = False
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic):
                dump = pkt.show(dump=True)
                if 'Port Description' in dump:
                    pdFound = True
                if pkt.haslayer(lldp_man_tlv):
                    maFound = True

        if not pdFound:
            self.passed('Captured LLDPDUs from {} no longer carry a Port Description TLV'.format(portA.name))
        else:
            self.failed('Captured LLDPDUs from {} still carry a Port Description TLV'.format(portA.name))

        if maFound:
            self.passed('Captured LLDPDUs from {} still carry the Management Address TLV (lldp_man_tlv), remaining selected TLV preserved'.format(portA.name))
        else:
            self.failed('Captured LLDPDUs from {} are missing the Management Address TLV although it remains selected'.format(portA.name))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select port-description management-address')
