    testCaseMethod += 'Verify: `show lldp interface <port>` shows system-description no longer selected; captured LLDPDUs no longer carry a System Description TLV but still carry the remaining selected TLVs.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Establish the precondition the step presumes: several optional base TLVs
        # selected on the test port, including system-description, so that main() can
        # clear ONLY system-description and prove the others remain selected.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select port-description system-name system-description system-capabilities management-address')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 270-282
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 17: Clear only the system-description TLV on the test port (`no lldp tlv-select system-description`), leaving the remaining optional TLVs selected, and capture LLDPDUs.')

        subProc = tb.start_tcpdump(ethA.name, '%s_%s.pcap' % (self.testCaseName, ethA.name), 'ether dst 01:80:c2:00:00:0e')

        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select system-description')
        dutA.mode('#')

        time.sleep(5)
        recPktList = tb.stop_tcpdump(subProc)

        output = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(output))

        portSuffix = portA.name[4:] if portA.name.startswith('port') else portA.name
        row = None
        for line in output.splitlines():
            tokens = line.split()
            if not tokens:
                continue
            portToken = tokens[0].lstrip('*')
            if portToken == portSuffix:
                row = tokens
                break

        if row is None:
            self.failed('port {} missing from show lldp interface output'.format(portA.name))
            return

        baseField = row[-4]
        if 'Sd' not in baseField and 'Pd' in baseField and 'Sn' in baseField and 'Sc' in baseField and 'Ma' in baseField:
            self.passed('show lldp interface {} Base TLVs column {} shows system-description cleared while port-description, system-name, system-capabilities and management-address remain selected'.format(portA.name, baseField))
        else:
            self.failed('show lldp interface {} Base TLVs column {} does not show system-description cleared with the other selected TLVs intact'.format(portA.name, baseField))

        if len(recPktList) == 0:
            self.failed('No LLDP frames captured on {} after clearing the system-description TLV'.format(ethA.name))
            return
        self.passed('{} LLDP frames captured on {} after clearing the system-description TLV'.format(len(recPktList), ethA.name))

        log_packet(self, recPktList[0])
        analyse_lldp_packets(self, recPktList)

        sysDescrSeen = False
        baseCapSeen = False
        for pkt in recPktList:
            if not pkt.haslayer(lldp_basic):
                continue
            raw = bytes(pkt)
            if b'Allied Telesis' in raw:
                sysDescrSeen = True
            if pkt.haslayer(lldp_base_cap_tlv):
                baseCapSeen = True

        if not sysDescrSeen:
            self.passed('Captured LLDPDUs no longer contain a System Description TLV (no system description string found in any decoded frame)')
        else:
            self.failed('Captured LLDPDUs still contain a System Description TLV string')

        if baseCapSeen:
            self.passed('Captured LLDPDUs still carry the remaining selected System Capabilities TLV')
        else:
            self.failed('Captured LLDPDUs no longer carry the remaining selected System Capabilities TLV')

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Undo configure() and the extra `no lldp tlv-select system-description` applied
        # in main(), restoring the port's default (no optional TLVs selected).
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select port-description system-name system-description system-capabilities management-address')
        dutA.mode('#')


