class TestCase_19(ATTestCase.TestCase):
    testCaseDesc = 'Clear only the management-address TLV on the test port (`no lldp tlv-select management-address`), leaving any remaining optional TLVs selected, and capture LLDPDUs.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'Clear only the management-address TLV on the test port (`no lldp tlv-select management-address`), leaving any remaining optional TLVs selected, and capture LLDPDUs.\n'
    testCaseMethod += 'Verify: `show lldp interface <port>` shows management-address no longer selected; captured LLDPDUs no longer carry a Management Address TLV but still carry any remaining selected TLVs.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition: select management-address plus one other optional base TLV
        # (system-capabilities) on the test port, so main() can clear ONLY
        # management-address and prove the other TLV survives the change.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select system-capabilities management-address')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 296-308
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 19: Clear only the management-address TLV on the test port (`no lldp tlv-select management-address`), leaving any remaining optional TLVs selected, and capture LLDPDUs.')

        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select management-address')
        dutA.cmd('shutdown')
        dutA.cmd('no shutdown')
        dutA.mode('#')

        wait_for_port_link_up(self, dutA, [portA])

        subProc = tb.start_tcpdump(ethA.name, '%s_%s.pcap' % (self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        cliOutput = dutA.cmd('show lldp interface {}'.format(portA.name))
        output = 'captured {} LLDPDU(s) on {}; show lldp interface {}:\n{}'.format(
            len(recPktList), ethA, portA.name, cliOutput)
        self.log('OBSERVED: {}'.format(output))

        if len(recPktList) == 0:
            self.failed('No LLDPDU captured on {} after clearing management-address TLV'.format(ethA))
            return
        self.passed('{} LLDPDU(s) captured on {}'.format(len(recPktList), ethA))

        log_packet(self, recPktList[0])
        analyse_lldp_packets(self, recPktList)

        row = None
        for line in cliOutput.splitlines():
            tokens = line.split()
            if tokens and tokens[0].lstrip('*') == portA.name:
                row = tokens
                break

        if row is None:
            self.failed('{} missing from show lldp interface output'.format(portA.name))
            return

        baseCol = row[-4]

        if 'Ma' not in baseCol:
            self.passed('show lldp interface {} Base TLVs column {} no longer advertises management-address (Ma)'.format(portA.name, baseCol))
        else:
            self.failed('show lldp interface {} Base TLVs column {} still advertises management-address (Ma), expected it cleared'.format(portA.name, baseCol))

        if 'Sc' in baseCol:
            self.passed('show lldp interface {} Base TLVs column {} still advertises system-capabilities (Sc)'.format(portA.name, baseCol))
        else:
            self.failed('show lldp interface {} Base TLVs column {} no longer advertises system-capabilities (Sc), expected it to remain selected'.format(portA.name, baseCol))

        manTlvSeen = False
        capTlvSeen = False
        for pkt in recPktList:
            if pkt.haslayer(lldp_man_tlv):
                manTlvSeen = True
            if pkt.haslayer(lldp_base_cap_tlv):
                capTlvSeen = True

        if not manTlvSeen:
            self.passed('captured LLDPDUs on {} carry no Management Address TLV'.format(ethA))
        else:
            self.failed('captured LLDPDUs on {} still carry a Management Address TLV, expected it removed'.format(ethA))

        if capTlvSeen:
            self.passed('captured LLDPDUs on {} still carry the System Capabilities TLV'.format(ethA))
        else:
            self.failed('captured LLDPDUs on {} no longer carry the System Capabilities TLV, expected it to remain selected'.format(ethA))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Mirror configure(): remove both TLV selections that were applied for this
        # test (management-address was already cleared in main(), but re-issuing the
        # `no` form here for both is idempotent and restores the pre-test state).
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select system-capabilities management-address')
        dutA.mode('#')


class TestCase_20(ATTestCase.TestCase):
    testCaseDesc = 'With LLDP still enabled, clear all remaining optional TLVs on the test port so none are selected, then capture several LLDPDUs.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'With LLDP still enabled, clear all remaining optional TLVs on the test port so none are selected, then capture several LLDPDUs.\n'
    testCaseMethod += 'Verify: Each captured LLDPDU carries only the Chassis ID, Port ID and Time To Live TLVs followed immediately by the End Of LLDPDU marker; no optional TLV appears on the wire.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Establish the precondition this step presumes: LLDP running on the test port with
        # optional TLVs selected, so that "clear all remaining optional TLVs" in main() has
        # something real to clear.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select all')
        dutA.cmd('lldp med-tlv-select all')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 335-344
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 20: With LLDP still enabled, clear all remaining optional TLVs on the test port so none are selected, then capture several LLDPDUs.')

        dutA.mode('#')
        probe = dutA.cmd('show lldp')
        if 'Invalid input' in probe or 'Unrecognized command' in probe:
            self.supported = False
            self.log('INFO: {} does not support lldp; case not applicable'.format(dutA))
            return

        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select all')
        dutA.cmd('no lldp med-tlv-select all')
        dutA.mode('#')

        output = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(output))

        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        # Force an immediate LLDPDU retransmission from the DUT so the capture window does not
        # have to span the full default (30s) transmit interval.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('shutdown')
        dutA.cmd('no shutdown')
        dutA.mode('#')
        wait_for_port_link_up(self, dutA, [portA])
        time.sleep(5)
        recPktList = tb.stop_tcpdump(subProc)

        if len(recPktList) == 0:
            self.failed('No LLDPDUs were captured on {} after clearing all optional TLVs'.format(portA.name))
            return
        self.passed('{} LLDPDU(s) captured on {} after clearing all optional TLVs'.format(len(recPktList), portA.name))

        analyse_lldp_packets(self, recPktList)

        optional_layers = [lldp_base_cap_tlv, lldp_cap_tlv, lldp_man_tlv, lldp_net_tlv,
                            lldp_sn_tlv, lldp_sw_tlv, lldp_mac_tlv]
        mandatory_only = True
        sawLldpBasic = False
        for idx, pkt in enumerate(recPktList):
            if not pkt.haslayer(lldp_basic):
                continue
            sawLldpBasic = True
            for layer in optional_layers:
                if pkt.haslayer(layer):
                    mandatory_only = False
                    self.log('packet {} unexpectedly carries optional layer {}'.format(idx + 1, layer.__name__))
            if not pkt.haslayer(lldp_end_tlv):
                mandatory_only = False
                self.log('packet {} is missing the End Of LLDPDU TLV'.format(idx + 1))

        if not sawLldpBasic:
            self.failed('None of the captured frames on {} decoded as an LLDPDU (Chassis ID/Port ID/TTL TLV)'.format(portA.name))
            return

        if mandatory_only:
            self.passed('Captured LLDPDUs on {} carry only Chassis ID, Port ID and TTL TLVs, terminated immediately by the End Of LLDPDU marker; no optional TLV present'.format(portA.name))
        else:
            self.failed('At least one captured LLDPDU on {} carried an optional TLV or lacked the End Of LLDPDU marker, contrary to the cleared TLV selection'.format(portA.name))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Mirror configure(): leave the optional TLV selection cleared (as main() left it) and
        # return the console to exec mode.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select all')
        dutA.cmd('no lldp med-tlv-select all')
        dutA.mode('#')


class TestCase_21(ATTestCase.TestCase):
    testCaseDesc = 'With LLDP running and only mandatory TLVs on the wire, select one additional optional TLV (e.g. `lldp tlv-select system-name`) without restarting LLDP or bouncing the port, and capture the next LLDPDUs.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'With LLDP running and only mandatory TLVs on the wire, select one additional optional TLV (e.g. `lldp tlv-select system-name`) without restarting LLDP or bouncing the port, and capture the next LLDPDUs.\n'
    testCaseMethod += 'Verify: The newly selected TLV appears in subsequent LLDPDUs without any LLDP or port restart, and transmission of the already-present mandatory TLVs is uninterrupted.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Establish the precondition this step presumes: LLDP running on portA with
        # only the mandatory (always-sent) TLVs on the wire, i.e. no optional TLVs
        # selected for transmission.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select all')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 283-295
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 21: With LLDP running and only mandatory TLVs on the wire, select one additional optional TLV (e.g. `lldp tlv-select system-name`) without restarting LLDP or bouncing the port, and capture the next LLDPDUs.')

        dutA.mode('#')
        probeOutput = dutA.cmd('show lldp interface {}'.format(portA.name))
        if 'Invalid input' in probeOutput or 'Unrecognized command' in probeOutput:
            self.supported = False
            self.log('INFO: {} does not support show lldp interface; case not applicable'.format(dutA))
            return

        # ---- Confirm baseline: only mandatory TLVs on the wire (no optional Base TLVs enabled)
        portToken = portA.name.replace('port', '')
        beforeRow = None
        for line in probeOutput.splitlines():
            tokens = line.strip().lstrip('*').split()
            if tokens[:1] == [portToken]:
                beforeRow = tokens
                break

        if beforeRow is None:
            self.failed('port {} missing from show lldp interface output'.format(portA.name))
            return

        baseBefore = beforeRow[-4]
        if baseBefore == '-' * len(baseBefore):
            self.passed('Baseline confirmed: no optional Base TLVs selected on {}, Base column = {}'.format(portA.name, baseBefore))
        else:
            self.failed('Baseline not mandatory-only: Base column on {} is {}, expected all dashes'.format(portA.name, baseBefore))

        # ---- Select one additional optional TLV without restarting LLDP or bouncing the port
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select system-name')
        dutA.mode('#')

        afterOutput = dutA.cmd('show lldp interface {}'.format(portA.name))
        afterRow = None
        for line in afterOutput.splitlines():
            tokens = line.strip().lstrip('*').split()
            if tokens[:1] == [portToken]:
                afterRow = tokens
                break

        if afterRow is None:
            self.failed('port {} missing from show lldp interface output after selecting system-name TLV'.format(portA.name))
            return

        baseAfter = afterRow[-4]
        self.log('OBSERVED: Base TLVs Enabled for Tx on {} changed from {} to {}'.format(portA.name, baseBefore, baseAfter))

        if len(baseAfter) >= 10 and baseAfter[2:4] == 'Sn' and baseAfter[0:2] == '--' and baseAfter[4:6] == '--' and baseAfter[6:8] == '--' and baseAfter[8:10] == '--':
            self.passed('System Name TLV (Sn) selected on {} without affecting the other optional Base TLVs (Base column now {})'.format(portA.name, baseAfter))
        else:
            self.failed('System Name TLV not correctly reflected in show lldp interface for {}: Base column is {}'.format(portA.name, baseAfter))

        # ---- Retrieve the configured system name from the CLI, to search for on the wire
        localInfo = dutA.cmd('show lldp local-info interface {}'.format(portA.name))
        sysName = None
        for line in localInfo.splitlines():
            if 'System Name' in line:
                sysName = line.split()[-1]
                break

        # ---- Capture the next LLDPDUs transmitted by the DUT, without restarting LLDP or the port
        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        self.log('Waiting for the DUT to transmit its next scheduled LLDPDU on {}'.format(portA.name))
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        if len(recPktList) == 0:
            self.failed('No LLDPDUs captured on {} after selecting the system-name TLV'.format(ethA))
            return

        self.passed('{} LLDPDUs captured on {} following the TLV selection'.format(len(recPktList), ethA))
        log_packet(self, recPktList[0])
        analyse_lldp_packets(self, recPktList)

        mandatoryOk = False
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic):
                if pkt[lldp_basic].chassis_id and pkt[lldp_basic].port_id and pkt[lldp_basic].ttl_val:
                    mandatoryOk = True
                    break

        if mandatoryOk:
            self.passed('Mandatory TLVs (chassis id, port id, ttl) still present in the captured LLDPDUs: transmission was uninterrupted')
        else:
            self.failed('Mandatory TLVs (chassis id, port id, ttl) not found in the captured LLDPDUs')

        sysNameFound = False
        if sysName:
            sysNameBytes = sysName.encode('utf-8')
            for pkt in recPktList:
                if pkt.haslayer(lldp_basic) and sysNameBytes in bytes(pkt):
                    sysNameFound = True
                    break

        if sysNameFound:
            self.passed('Newly selected System Name TLV value "{}" found in a captured LLDPDU without restarting LLDP or bouncing the port'.format(sysName))
        else:
            self.failed('Newly selected System Name TLV value ({}) was not found in any captured LLDPDU'.format(sysName))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Undo the optional TLV selected by main(); configure()'s baseline (no optional
        # TLVs) is left in its default state so it needs no further reversal.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select system-name')
        dutA.mode('#')


class TestCase_22(ATTestCase.TestCase):
    testCaseDesc = 'With LLDP running and several optional TLVs selected, clear one of them (`no lldp tlv-select <tlv>`) without restarting LLDP or the port, and capture the next LLDPDUs.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'With LLDP running and several optional TLVs selected, clear one of them (`no lldp tlv-select <tlv>`) without restarting LLDP or the port, and capture the next LLDPDUs.\n'
    testCaseMethod += 'Verify: The cleared TLV is absent from subsequent LLDPDUs while the remaining selected TLVs continue to be transmitted, with no LLDP or port restart.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Select two optional base TLVs on the test port: management-address (Ma) and
        # system-capabilities (Sc), so main() can clear one and prove the other survives.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select management-address system-capabilities')
        dutA.mode('#')

    def main(self):
        # ART 1332_lldp_med/test-1332.2001.py lines 300-340
        # helpers ART 1332_lldp_med/library_1332.py lines 10-15 and lines 44-81
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 22: With LLDP running and several optional TLVs selected, clear one of them (`no lldp tlv-select <tlv>`) without restarting LLDP or the port, and capture the next LLDPDUs.')

        portSuffix = portA.name[4:] if portA.name.startswith('port') else portA.name

        dutA.mode('#')
        baseline = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED baseline show lldp interface: {}'.format(baseline))
        if 'Invalid input' in baseline or 'Unrecognized command' in baseline:
            self.supported = False
            self.log('INFO: {} does not support show lldp interface; case not applicable'.format(dutA))
            return

        baseRow = next((l for l in baseline.splitlines() if l.split()[:1] == [portSuffix]), None)
        if baseRow is None or 'ScMa' not in baseRow.replace('*', ''):
            self.failed('port {} does not show both Sc and Ma enabled in show lldp interface before the change: {}'.format(portA.name, baseRow))
            return
        self.passed('management-address and system-capabilities TLVs both selected on {} before the change'.format(portA.name))

        counters_before = getPortCo(dutA, portA.name, interface=True)
        self.log('OBSERVED show interface (before): {}'.format(counters_before))

        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select system-capabilities')
        dutA.mode('#')
        time.sleep(5)
        recPktList = tb.stop_tcpdump(subProc)

        if len(recPktList) == 0:
            self.failed('No LLDP frames were captured on {} after clearing system-capabilities TLV'.format(ethA.name))
            return
        self.passed('{} LLDP frames captured on {} after clearing system-capabilities TLV'.format(len(recPktList), ethA.name))

        analyse_lldp_packets(self, recPktList)
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic):
                log_packet(self, pkt)

        clearedTlvPresent = any(pkt.haslayer(lldp_base_cap_tlv) for pkt in recPktList)
        remainingTlvPresent = any(pkt.haslayer(lldp_man_tlv) for pkt in recPktList)

        if not clearedTlvPresent:
            self.passed('lldp_base_cap_tlv (system-capabilities) is absent from all captured LLDPDUs after the clear')
        else:
            self.failed('lldp_base_cap_tlv (system-capabilities) is still present in a captured LLDPDU after `no lldp tlv-select system-capabilities`')

        if remainingTlvPresent:
            self.passed('lldp_man_tlv (management-address) is still present in captured LLDPDUs, remaining TLV unaffected')
        else:
            self.failed('lldp_man_tlv (management-address) is missing from captured LLDPDUs, remaining selected TLV was not transmitted')

        after = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED show lldp interface (after): {}'.format(after))
        afterRow = next((l for l in after.splitlines() if l.split()[:1] == [portSuffix]), None)
        if afterRow is None:
            self.failed('port {} missing from show lldp interface output after the change'.format(portA.name))
            return
        cleanRow = afterRow.replace('*', '')
        if '--Ma' in cleanRow or ('Ma' in cleanRow and 'Sc' not in cleanRow):
            self.passed('show lldp interface confirms Sc cleared and Ma still enabled on {}: {}'.format(portA.name, afterRow))
        else:
            self.failed('show lldp interface base flags on {} are {}, expected Sc cleared and Ma retained'.format(portA.name, afterRow))

        if afterRow.split()[1:3] == ['Rx', 'Tx']:
            self.passed('LLDP Rx/Tx still active on {} (Rx Tx), no LLDP restart observed'.format(portA.name))
        else:
            self.failed('LLDP Rx/Tx state on {} is {}, expected Rx Tx (unrestarted)'.format(portA.name, afterRow.split()[1:3]))

        counters_after = getPortCo(dutA, portA.name, interface=True)
        self.log('OBSERVED show interface (after): {}'.format(counters_after))
        if 'RUNNING' in counters_after:
            self.passed('port {} still shows RUNNING after the TLV clear, no port restart observed'.format(portA.name))
        else:
            self.failed('port {} no longer shows RUNNING after the TLV clear: {}'.format(portA.name, counters_after))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Revert both TLV selections applied by configure()/main() back to the default
        # (no optional TLVs selected on this port).
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select management-address system-capabilities')
        dutA.mode('#')


class TestCase_23(ATTestCase.TestCase):
    testCaseDesc = "Select a distinct set of optional TLVs on a second transmitting port (different from the test port's set), and capture LLDPDUs from the first test port."
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = "Select a distinct set of optional TLVs on a second transmitting port (different from the test port's set), and capture LLDPDUs from the first test port.\n"
    testCaseMethod += 'Verify: The TLVs transmitted on the first test port are unchanged by the configuration applied to the second port; `show lldp interface` for the first port shows its selection unaltered.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Establish the baseline optional-TLV selection on the first (test) port that
        # this step presumes and whose stability we are about to prove.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select management-address system-name')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 61-83
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log("STEP 23: Select a distinct set of optional TLVs on a second transmitting port (different from the test port's set), and capture LLDPDUs from the first test port.")

        def get_row(cmdOutput, name):
            for line in cmdOutput.splitlines():
                stripped = line.strip()
                if stripped.startswith('*'):
                    stripped = stripped[1:].strip()
                tokens = stripped.split()
                if tokens[:1] == [name]:
                    return line
            return None

        shortNameA = portA.name[4:] if portA.name.startswith('port') else portA.name

        dutA.mode('#')
        before_output = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: show lldp interface {} (before second-port change): {}'.format(portA.name, before_output))
        before_row = get_row(before_output, shortNameA)
        if before_row is None:
            self.failed('port {} missing from show lldp interface output before the second port was reconfigured'.format(portA.name))
            return
        self.passed('port {} TLV selection recorded before the second port was reconfigured: {}'.format(portA.name, before_row.strip()))

        self.log('Selecting a distinct set of optional TLVs on the second transmitting port {}'.format(portPeer.name))
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portPeer.name))
        dutA.cmd('lldp tlv-select port-description system-description')
        dutA.mode('#')

        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        self.log('Waiting for a periodic LLDPDU from {} to be captured on {}'.format(portA.name, ethA))
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        if len(recPktList) == 0:
            self.failed('No LLDP frames have been captured on {} after {} was reconfigured'.format(ethA, portPeer.name))
            return
        self.passed('{} LLDP frames have been captured on {} from the first test port'.format(len(recPktList), ethA))

        man_tlv_seen = False
        for pkt in recPktList:
            log_packet(self, pkt)
            if pkt.haslayer(lldp_man_tlv):
                man_tlv_seen = True

        if man_tlv_seen:
            self.passed('Management Address TLV (selected on {}) is still present in the LLDPDUs captured from the first test port'.format(portA.name))
        else:
            self.failed('Management Address TLV (selected on {}) is missing from the LLDPDUs captured from the first test port after {} was reconfigured'.format(portA.name, portPeer.name))

        after_output = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: show lldp interface {} (after second-port change): {}'.format(portA.name, after_output))
        after_row = get_row(after_output, shortNameA)
        if after_row is None:
            self.failed('port {} missing from show lldp interface output after {} was reconfigured'.format(portA.name, portPeer.name))
            return

        if after_row.split() == before_row.split():
            self.passed('show lldp interface {} TLV selection is unaltered after a distinct TLV selection was applied to {}: {}'.format(portA.name, portPeer.name, after_row.strip()))
        else:
            self.failed('show lldp interface {} TLV selection changed after {} was reconfigured: before={} after={}'.format(portA.name, portPeer.name, before_row.strip(), after_row.strip()))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Undo configure() (the first test port's baseline TLV selection) and the second
        # port's TLV selection applied during main(), command for command in `no` form.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select management-address system-name')
        dutA.cmd('interface {}'.format(portPeer.name))
        dutA.cmd('no lldp tlv-select port-description system-description')
        dutA.mode('#')


class TestCase_24(ATTestCase.TestCase):
    testCaseDesc = 'Leave one port with no optional TLVs selected while other ports transmit their selected optional TLVs, and capture LLDPDUs from each.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'Leave one port with no optional TLVs selected while other ports transmit their selected optional TLVs, and capture LLDPDUs from each.\n'
    testCaseMethod += 'Verify: The port with no optional TLVs selected transmits only the mandatory TLVs and end marker, while the other ports simultaneously transmit their selected optional TLVs — per-port independence holds.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition: portA has NO optional TLVs selected, portPeer has ALL optional
        # TLVs selected, so the two links can be compared for per-port independence.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select all')
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portPeer.name))
        dutA.cmd('lldp tlv-select all')
        dutA.mode('#')

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 335-344
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 24: Leave one port with no optional TLVs selected while other ports transmit their selected optional TLVs, and capture LLDPDUs from each.')

        dutA.mode('#')
        probe = dutA.cmd('show lldp')
        if 'Invalid input' in probe or 'Unrecognized command' in probe:
            self.supported = False
            self.log('INFO: {} does not support lldp; case not applicable'.format(dutA))
            return

        self.log('---- Capture the LLDPDU transmitted on portA (no optional TLVs selected)')
        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('shutdown')
        time.sleep(2)
        dutA.cmd('no shutdown')
        dutA.mode('#')
        wait_for_port_link_up(self, dutA, [portA], timeOut=30)
        time.sleep(5)
        recPktList = tb.stop_tcpdump(subProc)

        self.log('---- Retrieve the LLDPDU received by the peer on the portPeer link (optional TLVs selected)')
        peer.mode('#')
        peerOutput = peer.cmd('show lldp neighbors detail interface {}'.format(portDut.name))

        output = 'captured {} LLDPDU frame(s) on {} (portA); peer neighbor detail for {} (portPeer):\n{}'.format(
            len(recPktList), ethA.name, portDut.name, peerOutput)
        self.log('OBSERVED: {}'.format(output))

        if len(recPktList) == 0:
            self.failed('No LLDP frames captured on port {} with no optional TLVs selected'.format(portA.name))
            return
        self.passed('{} LLDP frame(s) captured on port {} with no optional TLVs selected'.format(len(recPktList), portA.name))

        analyse_lldp_packets(self, recPktList)

        portA_mandatory_found = False
        portA_end_found = False
        portA_optional_found = False
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic):
                portA_mandatory_found = True
            if pkt.haslayer(lldp_end_tlv):
                portA_end_found = True
            if pkt.haslayer(lldp_base_cap_tlv) or pkt.haslayer(lldp_man_tlv) or pkt.haslayer(lldp_net_tlv) or pkt.haslayer(lldp_sn_tlv) or pkt.haslayer(lldp_sw_tlv):
                portA_optional_found = True

        if portA_mandatory_found and portA_end_found:
            self.passed('port {} LLDPDU contains the mandatory base TLVs (chassis ID/port ID/TTL) and the end-of-LLDPDU marker'.format(portA.name))
        else:
            self.failed('port {} LLDPDU is missing mandatory base TLVs or the end-of-LLDPDU marker'.format(portA.name))
            return

        if not portA_optional_found:
            self.passed('port {} LLDPDU carries no optional TLVs, consistent with "no lldp tlv-select" on this port'.format(portA.name))
        else:
            self.failed('port {} LLDPDU unexpectedly contains optional TLVs even though none were selected on this port'.format(portA.name))

        if 'System Capabilities' in peerOutput and 'Management Addresses' in peerOutput:
            self.passed('peer neighbor detail for {} shows the System Capabilities and Management Addresses TLVs selected on port {}, independently of portA'.format(portDut.name, portPeer.name))
        else:
            self.failed('peer neighbor detail for {} does not show the optional TLVs selected on port {}'.format(portDut.name, portPeer.name))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select all')
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portPeer.name))
        dutA.cmd('no lldp tlv-select all')
        dutA.mode('#')


class TestCase_25(ATTestCase.TestCase):
    testCaseDesc = 'Set a spare port to transmit-only (`lldp transmit`, `no lldp receive`), select an optional TLV set on it, cable it to a partner that captures its LLDPDUs, and capture from that port.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'Set a spare port to transmit-only (`lldp transmit`, `no lldp receive`), select an optional TLV set on it, cable it to a partner that captures its LLDPDUs, and capture from that port.\n'
    testCaseMethod += "Verify: The transmit-only port's LLDPDUs carry exactly the selected optional TLVs, matching the result obtained on a transmit-and-receive port — receive capability is not a precondition for TLV transmission.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition: portA starts as a normal transmit-and-receive LLDP port with
        # exactly one optional TLV set (LLDP-MED inventory-management) selected on it.
        # main() will capture this baseline, then switch the port to transmit-only and
        # re-capture to prove the same TLV set is still transmitted.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp med-tlv-select all')
        dutA.cmd('lldp med-tlv-select inventory-management')
        dutA.mode('#')

    def main(self):
        # ART 1331_past_issues/test-1331.1001.py lines 760-784
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 25: Set a spare port to transmit-only (`lldp transmit`, `no lldp receive`), select an optional TLV set on it, cable it to a partner that captures its LLDPDUs, and capture from that port.')

        dutA.mode('#')
        output = dutA.cmd('show lldp')
        self.log('OBSERVED: {}'.format(output))
        if 'Invalid input' in output or 'Unrecognized command' in output:
            self.supported = False
            self.log('INFO: {} does not support lldp; case not applicable'.format(dutA))
            return

        def _inventory_tlvs_present(pktList):
            present = set()
            for pkt in pktList:
                if pkt.haslayer(lldp_hw_tlv):
                    present.add('hw')
                if pkt.haslayer(lldp_fw_tlv):
                    present.add('fw')
                if pkt.haslayer(lldp_sw_tlv):
                    present.add('sw')
                if pkt.haslayer(lldp_sn_tlv):
                    present.add('sn')
                if pkt.haslayer(lldp_man_tlv):
                    present.add('man')
                if pkt.haslayer(lldp_model_tlv):
                    present.add('model')
            return present

        def _extra_optional_tlvs_present(pktList):
            extras = set()
            for pkt in pktList:
                if pkt.haslayer(lldp_loc_tlv):
                    extras.add('location')
                if pkt.haslayer(lldp_net_tlv):
                    extras.add('network-policy')
                if pkt.haslayer(lldp_power_tlv):
                    extras.add('power-management-ext')
            return extras

        expected = set(['hw', 'fw', 'sw', 'sn', 'man', 'model'])

        self.log('---- Capturing LLDPDUs from {} while it is still transmit-and-receive (baseline)'.format(portA.name))
        subProc = tb.start_tcpdump(ethA.name, '{}_baseline.pcap'.format(self.testCaseName), 'ether proto 0x88cc')
        time.sleep(35)
        baselinePkts = tb.stop_tcpdump(subProc)

        if len(baselinePkts) == 0:
            self.failed('No LLDPDUs captured from {} while transmit and receive were both enabled'.format(portA.name))
            return
        self.passed('{} LLDPDUs captured from {} while transmit and receive were both enabled'.format(len(baselinePkts), portA.name))
        analyse_lldp_packets(self, baselinePkts)

        baselinePresent = _inventory_tlvs_present(baselinePkts)
        baselineExtras = _extra_optional_tlvs_present(baselinePkts)
        self.log('Baseline inventory-management TLVs present = {}, unexpected optional TLVs present = {}'.format(sorted(baselinePresent), sorted(baselineExtras)))
        if baselinePresent == expected and not baselineExtras:
            self.passed('Transmit-and-receive port {} carries exactly the selected inventory-management TLVs: {}'.format(portA.name, sorted(baselinePresent)))
        else:
            self.failed('Transmit-and-receive port {} inventory-management TLVs are {}, expected exactly {} with no other optional TLVs (extras: {})'.format(
                portA.name, sorted(baselinePresent), sorted(expected), sorted(baselineExtras)))
            return

        self.log('---- Setting {} to transmit-only (lldp transmit, no lldp receive)'.format(portA.name))
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp transmit')
        dutA.cmd('no lldp receive')
        dutA.mode('#')

        self.log('---- Capturing LLDPDUs from {} while it is transmit-only'.format(portA.name))
        subProc = tb.start_tcpdump(ethA.name, '{}_txonly.pcap'.format(self.testCaseName), 'ether proto 0x88cc')
        time.sleep(35)
        txOnlyPkts = tb.stop_tcpdump(subProc)

        if len(txOnlyPkts) == 0:
            self.failed('No LLDPDUs captured from {} while transmit-only (receive disabled)'.format(portA.name))
            return
        self.passed('{} LLDPDUs captured from {} while transmit-only'.format(len(txOnlyPkts), portA.name))
        analyse_lldp_packets(self, txOnlyPkts)

        txOnlyPresent = _inventory_tlvs_present(txOnlyPkts)
        txOnlyExtras = _extra_optional_tlvs_present(txOnlyPkts)
        self.log('Transmit-only inventory-management TLVs present = {}, unexpected optional TLVs present = {}'.format(sorted(txOnlyPresent), sorted(txOnlyExtras)))
        if txOnlyPresent == expected and not txOnlyExtras:
            self.passed('Transmit-only port {} carries exactly the selected inventory-management TLVs: {}'.format(portA.name, sorted(txOnlyPresent)))
        else:
            self.failed('Transmit-only port {} inventory-management TLVs are {}, expected exactly {} with no other optional TLVs (extras: {})'.format(
                portA.name, sorted(txOnlyPresent), sorted(expected), sorted(txOnlyExtras)))
            return

        if txOnlyPresent == baselinePresent:
            self.passed("The transmit-only port's LLDPDUs carry exactly the selected optional TLVs, matching the result obtained on a transmit-and-receive port — receive capability is not a precondition for TLV transmission.")
        else:
            self.failed("The transmit-only port's LLDPDUs carry exactly the selected optional TLVs, matching the result obtained on a transmit-and-receive port — receive capability is not a precondition for TLV transmission.")

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Undo main()'s transmit-only change and configure()'s TLV selection, in `no`
        # form, so the next case starts from the platform default LLDP state.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp receive')
        dutA.cmd('no lldp med-tlv-select inventory-management')
        dutA.cmd('lldp med-tlv-select capabilities network-policy location power-management-ext')
        dutA.mode('#')


class TestCase_26(ATTestCase.TestCase):
    testCaseDesc = 'On the test port select an LLDP-MED TLV (e.g. `lldp med-tlv-select capabilities`) independently of the basic optional TLV set, then toggle a basic optional TLV.'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod  = 'On the test port select an LLDP-MED TLV (e.g. `lldp med-tlv-select capabilities`) independently of the basic optional TLV set, then toggle a basic optional TLV.\n'
    testCaseMethod += 'Verify: `show lldp interface <port>` shows MED TLV selection independent of the basic optional TLV selection — changing one does not alter the other; the MED TLV set is separately selectable.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Reset the test port to a known baseline: no optional Base TLVs and no
        # optional LLDP-MED TLVs selected, so main() can toggle each independently
        # and observe a clean before/after.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select all')
        dutA.cmd('no lldp med-tlv-select all')
        dutA.mode('#')

    def main(self):
        # ART 1332_lldp_med/test-1332.1001.py lines 44-114
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 26: On the test port select an LLDP-MED TLV (e.g. `lldp med-tlv-select capabilities`) independently of the basic optional TLV set, then toggle a basic optional TLV.')

        portNum = portA.name[4:] if portA.name.startswith('port') else portA.name

        def get_row(output):
            for line in output.splitlines():
                if line.split()[:1] == [portNum]:
                    return line
            return None

        dutA.mode('#')
        probe = dutA.cmd('show lldp interface {}'.format(portA.name))
        if 'Invalid input' in probe or 'Unrecognized command' in probe:
            self.supported = False
            self.log('INFO: {} does not support show lldp interface; case not applicable'.format(dutA))
            return

        # Select only the LLDP-MED capabilities TLV, independently of any Base TLV.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        medOutput = dutA.cmd('lldp med-tlv-select capabilities')
        dutA.mode('#')

        if 'Invalid input' in medOutput or 'Unrecognized command' in medOutput:
            self.supported = False
            self.log('INFO: {} does not support lldp med-tlv-select capabilities; case not applicable'.format(dutA))
            return

        output1 = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(output1))
        row1 = get_row(output1)

        if row1 is None:
            self.failed('port {} missing from show lldp interface output after selecting MED capabilities TLV'.format(portA.name))
            return

        fields1 = row1.split()
        base1 = fields1[-4]
        med1 = fields1[-1]

        self.log('After MED select: Base column = {}, MED column = {}'.format(base1, med1))

        if 'Mc' in med1:
            self.passed('LLDP-MED capabilities TLV column shows Mc: {}'.format(med1))
        else:
            self.failed('LLDP-MED capabilities TLV not reflected in MED column: {}'.format(med1))
            return

        if base1.replace('-', '') == '':
            self.passed('Base optional TLV column unaffected by MED-only selection: {}'.format(base1))
        else:
            self.failed('Base optional TLV column unexpectedly non-empty after MED-only selection: {}'.format(base1))
            return

        # Now toggle a basic optional TLV (system-name) on the same port.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select system-name')
        dutA.mode('#')

        output2 = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(output2))
        row2 = get_row(output2)

        if row2 is None:
            self.failed('port {} missing from show lldp interface output after toggling system-name TLV'.format(portA.name))
            return

        fields2 = row2.split()
        base2 = fields2[-4]
        med2 = fields2[-1]

        self.log('After Base toggle: Base column = {}, MED column = {}'.format(base2, med2))

        if 'Sn' in base2:
            self.passed('Base optional TLV column now shows Sn after toggling system-name: {}'.format(base2))
        else:
            self.failed('Base optional TLV column did not reflect system-name toggle: {}'.format(base2))
            return

        if med2 == med1:
            self.passed('MED TLV column unchanged by Base TLV toggle: {} (was {})'.format(med2, med1))
        else:
            self.failed('MED TLV column changed after toggling a Base TLV: was {}, now {}'.format(med1, med2))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp tlv-select system-name')
