class TestCase_27(ATTestCase.TestCase):
    testCaseDesc = 'With the MED capabilities and network-policy MED TLVs selected on the test port, capture LLDPDUs and decode their organisationally specific TLVs.'
    testCaseRef = 'AWPTCM-T44297'
