        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Establish a known, non-default optional TLV selection on the test port so that
        # any change caused by a (mis-)accepted rejected keyword would be detectable.
