        self.log("STEP 32: After each of the three rejected keyword attempts, re-read the port's TLV selection.")

        def get_tlv_row(text, portName):
            shortName = portName.replace('port', '')
            for line in text.splitlines():
                parts = line.split()
                if parts and parts[0] in (portName, shortName, '*' + shortName):
                    return parts
            return None

        dutA.mode('#')
